SHELLver = 1.05;
var ImId = 0;
function SetImage(id,treeNumber,index,type){//id - id elementu, treeNumber - číslo knihovny, index - index ikony, type - 1 (true) = normální ikona, type - 0 (fALSE) - zobrazení metro ikon
	try{
		var el = document.getElementById(id);
		if (el.tagName.toLowerCase() == "img"){
			if (type)
				el.style.border = "1.2vh solid "+eval("ShellTree"+treeNumber+".ListBgReverse["+index+"]");
			else
				el.style.border = "none";
			if (isNaN(treeNumber))
				el.src = treeNumber;
			else
				el.src = eval("ShellTree"+treeNumber+".ListData["+index+"];");
		}
		else{
			if (type)
				el.innerHTML = "<div id='ic"+ImId+"' style='width: calc(100% - 2*(0.4vh)); height: calc(100% - 2*(0.4vh)); border: 0.4vh solid "+eval("ShellTree"+treeNumber+".ListBgReverse["+index+"]")+"; background-color: "+eval("ShellTree"+treeNumber+".ListBg["+index+"]")+";'><div id='icCon"+ImId+"' style='background-size: 100% 100%; background-repeat: no-repeat; left: 15%; top: 15%; width: 70%; height: 70%; position: absolute; background-image: url("+eval("ShellTree"+treeNumber+".ListData["+index+"];")+");'></div></div>";
			else{
				el.innerHTML = "";
				el.style.border = "none";
				if (isNaN(treeNumber))
					el.style.backgroundImage = "url("+treeNumber+")";
				else
					el.style.backgroundImage = "url("+eval("ShellTree"+treeNumber+".ListData["+index+"];")+")";
				el.style.backgroundRepeat = "no-repeat";
				el.style.backgroundSize = "100% 100%";
			}
		}
	}catch(erd){
		return undefined;
	}
}

function GetDataSetImage(treeNumber,index){//id - id elementu, treeNumber - číslo knihovny, index - index ikony, type - 1 (true) = normální ikona, type - 0 (fALSE) - zobrazení metro ikon
	return eval("ShellTree"+treeNumber+".ListData["+index+"];");
}

